import React, { forwardRef, useContext } from 'react';
import styled from 'styled-components';

import Animations from '@dynatrace/strato-design-tokens/animations';
import Borders from '@dynatrace/strato-design-tokens/borders';
import Colors from '@dynatrace/strato-design-tokens/colors';
import Spacings from '@dynatrace/strato-design-tokens/spacings';
import Typography from '@dynatrace/strato-design-tokens/typography';

import { TerminologyOverlayContext } from './TerminologyOverlayContext.js';
import type { CSSFocusStylesObject } from '../../core/hooks/useFocusRing.js';
import { useFocusRing } from '../../core/hooks/useFocusRing.js';
import type { DataTestId } from '../../core/types/data-props.js';
import type { DOMProps } from '../../core/types/dom.js';
import type { StylingProps } from '../../core/types/styling-props.js';
import { mergeProps as _mergeProps } from '../../core/utils/merge-props.js';

//#region Typings
export interface TerminologyOverlayTriggerProps
  extends DOMProps,
    StylingProps,
    DataTestId {
  /**
   * Trigger Overlay button must contain children elements.
   */
  children: React.ReactNode;
}
//#endregion Typings

// #region StyledComponents
const StyledTriggerButton = /* @__PURE__ */ styled('button')<{
  $focusStyle?: CSSFocusStylesObject;
  $isFocusVisible: boolean;
}>(({ $focusStyle, $isFocusVisible }) => ({
  border: 'none',
  borderRadius: Borders.Radius.Field.Subdued,
  background: Colors.Background.Field.Neutral.Default,
  color: Colors.Text.Neutral.Default,
  padding: Spacings.Size0,
  paddingInline: Spacings.Size2,
  fontWeight: Typography.Text.Base.Default.Weight,
  fontFamily: Typography.Text.Base.Default.Family,
  lineHeight: 'inherit',
  fontSize: 'inherit',
  cursor: 'pointer',
  outline: 'none',
  textDecoration: 'underline',
  textDecorationStyle: 'dashed',
  textUnderlineOffset: Spacings.Size4,
  textDecorationThickness: Borders.Width.Default,
  textDecorationColor: Colors.Border.Neutral.Accent,
  transition: `background-color ${Animations.Hover.Duration.Base} ${Animations.Hover.Easing}`,

  '&:hover': {
    backgroundColor: Colors.Background.Field.Neutral.DefaultHover,
  },
  '&:active': {
    background: Colors.Background.Field.Neutral.DefaultActive,
  },
  ...$focusStyle,
  ...($isFocusVisible && {
    textDecoration: 'none',
  }),
}));
// #endregion

/**
 * TerminologyOverlay Trigger component, used for rendering trigger content.
 */
export const Trigger = /* @__PURE__ */ forwardRef<
  HTMLButtonElement,
  TerminologyOverlayTriggerProps
>((props, forwardedRef) => {
  const {
    children,
    className: consumerClassName,
    style: consumerStyle,
    'data-testid': dataTestId,
  } = props;
  const { focusProps, focusStyles, isFocusVisible } = useFocusRing({
    isMinimal: true,
  });
  const overlayTriggerProps = useContext(TerminologyOverlayContext);

  return (
    <StyledTriggerButton
      data-testid={dataTestId}
      className={consumerClassName}
      style={consumerStyle}
      ref={forwardedRef}
      $focusStyle={focusStyles}
      $isFocusVisible={isFocusVisible}
      {..._mergeProps(overlayTriggerProps, focusProps)}
      aria-haspopup="dialog"
    >
      {children}
    </StyledTriggerButton>
  );
});

(Trigger as typeof Trigger & { displayName: string }).displayName =
  'TerminologyOverlay.Trigger';
